package uz.plugin.video_player

/**
 * What Dart calls through JNI (bindings in `lib/src/bindings/`, generated by `dart run tool/jnigen.dart`). Only
 * primitives and [String] cross the boundary; the outcome comes back through [PlayCallback], so a call returns at
 * once and native code never blocks on Dart. Every [playVideo] answers its callback exactly once. Before an engine
 * attaches, calls answer `NOT_ATTACHED`.
 *
 * The embedded platform view keeps its own per-view method channel and is not part of this API.
 */
object VideoPlayerApi {

    /** Outcome of one [playVideo] call; exactly one method is invoked, on the main thread. */
    interface PlayCallback {
        /** The user finished or left the player; positions are in SECONDS. */
        fun onFinished(positionSeconds: Int, durationSeconds: Int)

        /** The session ended without a position (cancelled, or the host went away). */
        fun onCancelled()

        fun onError(code: String, message: String)
    }

    @Volatile
    internal var host: VideoPlayerPlugin? = null

    @JvmStatic
    fun playVideo(playerConfigJson: String, callback: PlayCallback) {
        val current = host
        if (current == null) {
            callback.onError("NOT_ATTACHED", "video_player is not attached to an engine")
        } else {
            current.playVideo(playerConfigJson, callback)
        }
    }

    @JvmStatic
    fun close() {
        host?.close()
    }
}
